using System.Text.Json;
using OcctSharp.ConfiguredMeshExchange;
using OcctSharp.DocumentProjections;
using OcctSharp.DocumentAssociations;
using OcctSharp.StepCafWorkspaces;
using OcctSharp.MeshingWorkspaces;
using OcctSharp.XdeMetadataWorkspaces;
namespace OcctSharp.Tests.Shared;

internal static class BatchBKConfiguredMeshWorkflow {
 internal static void Require(bool condition,string message){if(!condition)throw new InvalidOperationException("BK: "+message);}
 internal static LocalStepTransferResult Assembly(){var manifest=LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,BatchBJLocalStepWorkflow.AssemblyFiles);using var workspace=LocalStepAssemblyWorkspace.Open(BatchBJLocalStepWorkflow.Fixture,"assembly.step",manifest);return workspace.Transfer([workspace.Roots[0].Id]);}
 internal static readonly MeshCoordinateConfiguration ToGltf=new(.001,MeshUpAxis.Z,1,MeshUpAxis.Y);
 internal static readonly MeshCoordinateConfiguration FromGltf=new(1,MeshUpAxis.Y,.001,MeshUpAxis.Z);
 internal static readonly CommonMaterialValues Common=new(new(.1,.2,.3),new(.25,.5,.75),new(.3,.2,.1),new(0,0,0),25,.2);
 internal static void MeshDefinitions(LocalStepTransferResult assembly,DocumentProjectionContext context){
  Require(assembly.Completed&&assembly.Document is not null,"actual STEP assembly transfer");using var relations=DocumentAssociationContext.Bind(context);assembly.Document!.NewCommand();
  try{foreach(string definition in assembly.Occurrences.Select(x=>x.DefinitionEntry).Distinct(StringComparer.Ordinal)){int occurrence=assembly.Occurrences.ToList().FindIndex(x=>x.DefinitionEntry==definition)+1;using var located=assembly.CopyOccurrence(occurrence);var box=located.GetBoundingBox();Require(Math.Abs(box.Minimum.X)<1e-5,"chosen first definition copy is at its original identity placement");using var mesh=ControlledMeshing.Run(located,new(Deflection:.05));Require(mesh.IsDone&&mesh.HasCompleteTriangulation,"controlled independent definition mesh");using var copy=mesh.CopyShape();ConfiguredMeshFiles.ReplaceTriangulatedDefinition(context,context.GetLabel(definition),copy);}Require(assembly.Document.CommitCommand(),"definition mesh command commit");}
  catch{assembly.Document.AbortCommand();throw;}
  foreach(var occurrence in assembly.Occurrences){var actual=relations.Snapshot(context.GetLabel(occurrence.Entry)).Assembly;Require(actual?.ReferredEntry==occurrence.DefinitionEntry,"unchanged exact occurrence relationship after mesh writeback");}
 }
 internal static void Run(){
  BatchBGModelingWorkflow.Run();BatchBHIntersectionWorkflow.Run();
  string root=Path.Combine(Path.GetTempPath(),"OcctSharp.BK."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  try{
   using var assembly=Assembly();BatchBJLocalStepWorkflow.Verify(assembly);using var context=DocumentProjectionContext.Bind(assembly.Document!);MeshDefinitions(assembly,context);using var metadata=XdeMetadataContext.Bind(context);var definition=context.GetLabel(assembly.Occurrences[0].DefinitionEntry);
   assembly.Document!.NewCommand();var material=metadata.CreateMaterial("BK combined material",new(.25,.5,.75,1),.3,.6,[definition]);ConfiguredMeshFiles.ReplaceCommon(context,material,Common);context.ReplaceCollection(context.GetLabel(assembly.FreeRoots[0].Entry),DirectCollections.List<string>(LocalStepAssemblyWorkspace.CaptureManifest(BatchBJLocalStepWorkflow.Fixture,BatchBJLocalStepWorkflow.AssemblyFiles).Select(x=>x.Sha256)));Require(assembly.Document.CommitCommand(),"BI material/source command commit");
   var common=ConfiguredMeshFiles.ReadCommon(context,material);Require(common?.Values is {} values&&Math.Abs(values.Diffuse.Green-.5)<1e-6&&Math.Abs(values.Shininess-25)<1e-6,"copied Common material");var preserved=metadata.Snapshot().Materials.Single(x=>x.Entry==material.Entry).Pbr;Require(preserved is not null&&Math.Abs(preserved.Metallic-.3)<1e-6,"Common replacement preserves existing PBR");
   string gltf=Path.Combine(root,"assembly.gltf");var written=ConfiguredMeshFiles.WriteNew(context,gltf,ConfiguredMeshFormat.Gltf,ToGltf,Common,[new("Author","OcctSharp BK")]);Require(written.AppliedCoordinates==ToGltf&&written.AppliedDefaultStyle?.Values is not null&&written.Files.Count>=2&&written.RequestedWriteMetadata["Author"]=="OcctSharp BK","private converter/default style/copied files");
   using(var read=ConfiguredMeshFiles.Read(gltf,ConfiguredMeshFormat.Gltf,FromGltf)){Require(read.Diagnostics.AppliedCoordinates==FromGltf&&read.Diagnostics.NativeExtraStatus==0&&read.Diagnostics.FreeRoots.Count==1,"complete glTF read configuration");using var readContext=DocumentProjectionContext.Bind(read.Document);var rootLabel=readContext.GetLabel(read.Diagnostics.FreeRoots[0].Entry);using var exactRelations=DocumentAssociationContext.Bind(readContext);var imported=exactRelations.Snapshot(rootLabel).Assembly;Require(imported is not null&&imported.ComponentEntries.Count==2,"glTF repeated occurrence structure");var a=exactRelations.Snapshot(readContext.GetLabel(imported!.ComponentEntries[0])).Assembly;var b=exactRelations.Snapshot(readContext.GetLabel(imported.ComponentEntries[1])).Assembly;if(Environment.GetEnvironmentVariable("OCCTSHARP_BATCH_BK_EVIDENCE") is {} debug){Directory.CreateDirectory(debug);var rows=new List<object>();void Walk(string entry,int depth){if(depth>16||rows.Count>512)return;var value=exactRelations.Snapshot(readContext.GetLabel(entry)).Assembly;rows.Add(new{entry,depth,value});if(value is null)return;if(value.ReferredEntry is {} referred)Walk(referred,depth+1);foreach(var child in value.ComponentEntries)Walk(child,depth+1);}Walk(rootLabel.Entry,0);File.WriteAllText(Path.Combine(debug,"roundtrip-structure.json"),JsonSerializer.Serialize(rows));File.Copy(gltf,Path.Combine(debug,"roundtrip.gltf"),true);}Require(a?.ReferredEntry is not null&&a.ReferredEntry==b?.ReferredEntry,"glTF shared definition");var mesh=MeshTopology.SnapshotExisting(read.Shape).Mesh;double dx=mesh.Positions.Max(p=>p.X)-mesh.Positions.Min(p=>p.X),dy=mesh.Positions.Max(p=>p.Y)-mesh.Positions.Min(p=>p.Y),dz=mesh.Positions.Max(p=>p.Z)-mesh.Positions.Min(p=>p.Z);Require(Math.Abs(dx-12)<1e-4&&Math.Abs(dy-3)<1e-4&&Math.Abs(dz-4)<1e-4,"glTF exact unit/axis/instance placement readback");read.Document.Dispose();Require(MeshTopology.SnapshotExisting(read.Shape).Mesh.Triangles.Count>0,"owned triangulated shape after imported document closure");}
   string obj=Path.Combine(root,"assembly.obj");var objCoordinates=new MeshCoordinateConfiguration(.001,MeshUpAxis.Z,.001,MeshUpAxis.Y);ConfiguredMeshFiles.WriteNew(context,obj,ConfiguredMeshFormat.Obj,objCoordinates,Common);using(var read=ConfiguredMeshFiles.Read(obj,ConfiguredMeshFormat.Obj,new(.001,MeshUpAxis.Y,.001,MeshUpAxis.Z))){var mesh=MeshTopology.SnapshotExisting(read.Shape).Mesh;Require(mesh.Triangles.Count>0&&Math.Abs(mesh.Positions.Max(p=>p.X)-mesh.Positions.Min(p=>p.X)-12)<1e-4,"OBJ explicit coordinate readback");}
   BatchBKWireChecks.Check(gltf);using var json=JsonDocument.Parse(File.ReadAllBytes(gltf));Require(json.RootElement.GetProperty("meshes").EnumerateArray().SelectMany(x=>x.GetProperty("primitives").EnumerateArray()).All(x=>x.GetProperty("attributes").TryGetProperty("NORMAL",out _)),"actual glTF normal channels");
   string evidence=Environment.GetEnvironmentVariable("OCCTSHARP_BATCH_BK_EVIDENCE")??Path.Combine(root,"viewer-evidence");BatchBKRawMeshViewer.Run(gltf,evidence);assembly.Dispose();Require(common?.Values is not null&&written.Files.Count>0,"detached configuration/material diagnostics after closure");
  }finally{Directory.Delete(root,true);}
 }
}
